/** A standings row: team, wins, losses, made the playoffs (1). A plain string is a division or conference heading. */
export type StandingRow = string | [team: string, wins: number, losses: number, playoffs: number];
/** Round, winner, loser, series result (winner's wins first). */
export type Series = [round: string, winner: string, loser: string, result: string];
/** Rank, player, team abbreviation, first-place votes, vote share (0 to 1). */
export type Vote = [rank: string, player: string, team: string, first: number | null, share: number | null];
/** Overall pick, team abbreviation, player, college or club. */
export type Pick = [pick: number | null, team: string, player: string, college: string];

export interface BBSeason {
  standings?: StandingRow[][];
  playoffs?: Series[];
  mvp?: Vote[];
  roy?: Vote[];
  draft?: Pick[];
}

